checkRuns.command:
python3 - <<'EOF'
p='src/components/book-list.kay'
s=open(p).read()
s=s[:s.index('\nstyle\n')]+'\n'
open(p,'w').write(s)
EOF
cat > src/app.css <<'EOF'
body { font-family: system-ui, sans-serif; max-width: 48rem; margin: 0 auto; padding: 1rem; line-height: 1.5; }
header { display: flex; gap: 1.5rem; align-items: center; border-bottom: 1px solid #ddd; padding-bottom: 0.5rem; }
header nav { display: flex; gap: 1rem; }
nav a[aria-current="page"] { font-weight: bold; }
footer { border-top: 1px solid #ddd; margin-top: 2rem; padding-top: 0.5rem; color: #666; }
.filter { display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 1rem; }
.filter button[aria-pressed="true"] { font-weight: bold; }
.meta, .favorite { margin-left: 0.5rem; }
.tags { display: flex; gap: 0.5rem; list-style: none; padding: 0; }
.field { display: flex; flex-direction: column; margin-bottom: 1rem; max-width: 24rem; }
.error { color: #b00020; margin: 0.25rem 0 0; }
EOF
sed -i '2a import '"'"'../app.css'"'"'' src/routes/_layout.kay; head -4 src/routes/_layout.kay
cat > src/routes/contact.kay <<'EOF'
--- server
import { t } from 'kay'
import { checkContact } from '../contact'
import ContactForm from '../components/contact-form.kay'

export const contact = action(t.Object({
  name: t.String({ maxLength: 200 }),
  email: t.String({ maxLength: 320 }),
  message: t.String({ maxLength: 5000 }),
}), (input, ctx) => {
  const errors = checkContact(input)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: input.name.trim() }
})
---
head
  title Contact
h1 Contact
ContactForm
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { contact } from '../routes/contact.kay'
import { checkContact } from '../contact'
import type { ContactErrors } from '../contact'

const errors = signal<ContactErrors>(contact.failed()?.data?.errors ?? {})
const thanked = signal(contact.succeeded()?.data.name ?? '')

async function submit(event: SubmitEvent) {
  event.preventDefault()
  const form = event.currentTarget as HTMLFormElement
  const fields = new FormData(form)
  const found = checkContact({
    name: String(fields.get('name') ?? ''),
    email: String(fields.get('email') ?? ''),
    message: String(fields.get('message') ?? ''),
  })

  errors.set(found)
  thanked.set('')

  if (Object.keys(found).length === 0) {
    try {
      thanked.set((await contact(fields, { refresh: false })).name)
      form.reset()
    }
    catch (error) {
      const data = (error as { data?: { errors?: ContactErrors } }).data
      errors.set(data?.errors ?? {})
    }
  }
}
---
if thanked
  p.success(role="status") Thanks, {thanked}! Your message has been sent.
form(action={contact} novalidate onSubmit={submit})
  .field
    label(for="name") Name
    input#name(type="text" name="name")
    if errors.name
      p.error {errors.name}
  .field
    label(for="email") Email
    input#email(type="email" name="email")
    if errors.email
      p.error {errors.email}
  .field
    label(for="message") Message
    textarea#message(name="message")
    if errors.message
      p.error {errors.message}
  button(type="submit") Send
EOF
bun run check

